use core::ffi::{c_char, c_int, c_long, c_uint, c_ulong, c_void};
use core::mem::size_of;
use core::ptr;

/* C include dependencies intentionally remain external to this translation:
 * errno, inttypes, stdlib, string, asm/bug, linux helpers, perf/subcmd
 * headers, and the local perf headers listed in the original source.
 */

type u8 = u8;
type u32 = u32;
type u64 = u64;
type int64_t = i64;
type size_t = usize;
type FILE = c_void;
type bool_ = bool;

const NULL: *mut c_void = ptr::null_mut();
const ENOMEM: c_int = 12;
const EINVAL: c_int = 22;
const ESRCH: c_int = 3;
const STRERR_BUFSIZE: usize = 128;
const SYMBOL_WIDTH: c_int = 50;
const HIST_FILTER__C2C: u8 = 1;
const PERF_DATA_MODE_READ: c_int = 0;
const PARSE_OPT_STOP_AT_NON_OPTION: c_int = 0;
const PARSE_OPT_KEEP_UNKNOWN: c_int = 0;
const PERF_SAMPLE_REGS_USER: u64 = 1 << 0;
const PERF_SAMPLE_STACK_USER: u64 = 1 << 1;
const PERF_SAMPLE_BRANCH_STACK: u64 = 1 << 2;
const PERF_SAMPLE_CALLCHAIN: u64 = 1 << 3;
const CALLCHAIN_NONE: perf_call_graph_mode = 0;
const CALLCHAIN_DWARF: perf_call_graph_mode = 1;
const CALLCHAIN_LBR: perf_call_graph_mode = 2;
const CALLCHAIN_FP: perf_call_graph_mode = 3;
const CHAIN_NONE: c_int = 0;
const NO_ADDR: u64 = !0u64;
const EM_AARCH64: c_int = 183;
const PERF_MEM_EVENTS__LOAD_STORE: usize = 0;
const PERF_MEM_EVENTS__LOAD: usize = 1;
const PERF_MEM_EVENTS__STORE: usize = 2;
const DISPLAY_LINE_LIMIT: f64 = 0.001;
const CALLCHAIN_DEFAULT_OPT: &[u8] = b"graph,0.5,caller,function,percent\0";

type perf_call_graph_mode = c_int;
type hists__resort_cb_t = Option<unsafe extern "C" fn(*mut hist_entry, *mut c_void) -> c_int>;
type get_percent_cb = unsafe extern "C" fn(*mut c2c_hist_entry) -> f64;

type new_fn_t = unsafe extern "C" fn(size_t) -> *mut c_void;
type free_fn_t = unsafe extern "C" fn(*mut c_void);
type hpp_fn_t = unsafe extern "C" fn(*mut perf_hpp_fmt, *mut perf_hpp, *mut hist_entry) -> c_int;
type hpp_color_fn_t = unsafe extern "C" fn(*mut perf_hpp_fmt, *mut perf_hpp, *mut hist_entry) -> c_int;
type hpp_cmp_fn_t = unsafe extern "C" fn(*mut perf_hpp_fmt, *mut hist_entry, *mut hist_entry) -> int64_t;
type hpp_header_fn_t = unsafe extern "C" fn(*mut perf_hpp_fmt, *mut perf_hpp, *mut hists, c_int, *mut c_int) -> c_int;
type hpp_width_fn_t = unsafe extern "C" fn(*mut perf_hpp_fmt, *mut perf_hpp, *mut hists) -> c_int;

#[repr(C)] struct list_head { next: *mut list_head, prev: *mut list_head }
#[repr(C)] struct rb_node { __rb_parent_color: c_ulong, rb_right: *mut rb_node, rb_left: *mut rb_node }
#[repr(C)] struct rb_root_cached { rb_root: *mut rb_node, rb_leftmost: *mut rb_node }
#[repr(C)] struct stats { n: u64, mean: f64, M2: f64 }
#[repr(C)] struct compute_stats { lcl_hitm: stats, rmt_hitm: stats, lcl_peer: stats, rmt_peer: stats, load: stats }

#[repr(C)] struct c2c_stats {
    nr_entries: u32, locks: u32, load: u32, ld_uncache: u32, ld_io: u32, ld_miss: u32,
    ld_noadrs: u32, ld_fbhit: u32, ld_l1hit: u32, ld_l2hit: u32, ld_llchit: u32,
    lcl_hitm: u32, rmt_hitm: u32, tot_hitm: u32, rmt_hit: u32, lcl_dram: u32,
    rmt_dram: u32, ld_excl: u32, ld_shared: u32, blk_data: u32, blk_addr: u32,
    lcl_peer: u32, rmt_peer: u32, tot_peer: u32, store: u32, st_uncache: u32,
    st_noadrs: u32, st_l1hit: u32, st_l1miss: u32, st_na: u32, nomap: u32, noparse: u32,
}

#[repr(C)] struct perf_tool {
    sample: Option<unsafe extern "C" fn(*const perf_tool, *mut perf_event, *mut perf_sample, *mut machine) -> c_int>,
    mmap: Option<unsafe extern "C" fn()>, mmap2: Option<unsafe extern "C" fn()>, comm: Option<unsafe extern "C" fn()>,
    exit: Option<unsafe extern "C" fn()>, fork: Option<unsafe extern "C" fn()>, lost: Option<unsafe extern "C" fn()>,
    attr: Option<unsafe extern "C" fn()>, auxtrace_info: Option<unsafe extern "C" fn()>, auxtrace: Option<unsafe extern "C" fn()>,
    auxtrace_error: Option<unsafe extern "C" fn()>, ordering_requires_timestamps: bool,
}
#[repr(C)] struct mem2node { _private: [u8; 0] }
#[repr(C)] struct perf_cpu { cpu: c_int }
#[repr(C)] struct perf_cpu_map { _private: [u8; 0] }
#[repr(C)] struct numa_node { map: *mut perf_cpu_map }
#[repr(C)] struct perf_env { nr_numa_nodes: c_int, nr_cpus_avail: c_int, numa_nodes: *mut numa_node }
#[repr(C)] struct evlist { _private: [u8; 0] }
#[repr(C)] struct evsel { _private: [u8; 0] }
#[repr(C)] struct perf_data { mode: c_int, path: *const c_char, force: bool }
#[repr(C)] struct perf_session { evlist: *mut evlist, data: *mut perf_data, itrace_synth_opts: *mut itrace_synth_opts }
#[repr(C)] struct itrace_synth_opts { set: bool, mem: bool, default_no_sample: bool }
#[repr(C)] struct ui_progress { _private: [u8; 0] }
#[repr(C)] struct perf_event_header { type_: u32 }
#[repr(C)] struct perf_event { header: perf_event_header }
#[repr(C)] struct perf_sample { evsel: *mut evsel, cpu: u32, phys_addr: u64, period: u64, file_offset: u64, weight: u64 }
#[repr(C)] struct machine { env: *mut perf_env }
#[repr(C)] struct thread { _private: [u8; 0] }
#[repr(C)] struct symbol { _private: [u8; 0] }
#[repr(C)] struct annotated_source { _private: [u8; 0] }
#[repr(C)] struct map_symbol { sym: *mut symbol }
#[repr(C)] struct addr_location { thread: *mut thread }
#[repr(C)] struct addr_map_symbol { addr: u64, al_addr: u64 }
#[repr(C)] struct mem_info { _private: [u8; 0] }
#[repr(C)] struct callchain_cursor { _private: [u8; 0] }
#[repr(C)] struct callchain_param { enabled: bool, mode: c_int, record_mode: perf_call_graph_mode, min_percent: c_int }
#[repr(C)] struct symbol_conf_t { use_callchain: bool, vmlinux_name: *const c_char, force: bool, priv_size: size_t }
#[repr(C)] struct annotate_opts_t { disassembler_style: *mut c_char, objdump_path: *mut c_char }

#[repr(C)] struct hist_entry {
    filtered: u8, hists: *mut hists, mem_info: *mut mem_info, thread: *mut thread, srcline: *mut c_char,
    rb_node: rb_node, ms: map_symbol,
}
#[repr(C)] struct hists_stats { total_period: u64, total_non_filtered_period: u64 }
#[repr(C)] struct hists { entries: rb_root_cached, stats: hists_stats, nr_entries: u64, hpp_list: *mut perf_hpp_list }
#[repr(C)] struct perf_hpp { buf: *mut c_char, size: size_t }
#[repr(C)] struct perf_hpp_fmt {
    list: list_head, sort_list: list_head, user_len: size_t,
    cmp: hpp_cmp_fn_t, sort: hpp_cmp_fn_t, color: hpp_color_fn_t, entry: hpp_fn_t,
    header: hpp_header_fn_t, width: hpp_width_fn_t, collapse: hpp_cmp_fn_t,
    equal: Option<unsafe extern "C" fn(*mut perf_hpp_fmt, *mut perf_hpp_fmt) -> bool>,
    free: Option<unsafe extern "C" fn(*mut perf_hpp_fmt)>,
}
#[repr(C)] struct perf_hpp_list { nr_header_lines: c_int, dso: c_int, sym: c_int }
#[repr(C)] struct sort_entry {
    se_width_idx: c_int, se_header: *const c_char,
    se_snprintf: unsafe extern "C" fn(*mut hist_entry, *mut c_char, size_t, size_t) -> c_int,
    se_cmp: unsafe extern "C" fn(*mut hist_entry, *mut hist_entry) -> int64_t,
    se_collapse: Option<unsafe extern "C" fn(*mut hist_entry, *mut hist_entry) -> int64_t>,
}
#[repr(C)] #[derive(Copy, Clone)] struct c2c_header_line { text: *const c_char, span: c_int }
#[repr(C)] #[derive(Copy, Clone)] struct c2c_header { line: [c2c_header_line; 2] }
#[repr(C)] struct c2c_dimension {
    header: c2c_header, name: *const c_char, cmp: hpp_cmp_fn_t, entry: hpp_fn_t,
    color: hpp_color_fn_t, width: c_int, se: *mut sort_entry,
}
#[repr(C)] struct c2c_fmt { fmt: perf_hpp_fmt, dim: *mut c2c_dimension }
#[repr(C)] struct c2c_hists { hists: hists, list: perf_hpp_list, stats: c2c_stats }
#[repr(C)] struct c2c_hist_entry {
    he: hist_entry, cpuset: *mut c_ulong, nodeset: *mut c_ulong, node_stats: *mut c2c_stats,
    cstats: compute_stats, hists: *mut c2c_hists, nodestr: *mut c_char, evsel: *mut evsel,
    paddr_zero: bool, paddr: u64, paddr_cnt: c_ulong, cacheline_idx: u32, stats: c2c_stats,
}
#[repr(C)] struct hist_entry_ops { new: new_fn_t, free: free_fn_t }
#[repr(C)] struct option { _private: [u8; 0] }
#[repr(C)] struct hist_browser { hists: *mut hists, he_selection: *mut hist_entry, nr_non_filtered_entries: u64, c2c_filter: bool, title: Option<unsafe extern "C" fn(*mut hist_browser, *mut c_char, size_t) -> c_int>, b: ui_browser }
#[repr(C)] struct ui_browser { _private: [u8; 0] }
#[repr(C)] struct c2c_function_view_args { cl_hists: *mut c2c_hists, cl_sort: *mut c_char, symbol_full: bool, browse_cacheline: Option<unsafe extern "C" fn(*mut hist_entry) -> c_int> }
#[repr(C)] struct perf_mem_event { tag: *const c_char }
#[repr(C)] struct perf_pmu { _private: [u8; 0] }

#[repr(C)] struct perf_c2c {
    tool: perf_tool,
    hists: c2c_hists,
    mem2node: mem2node,
    nodes: *mut *mut c_ulong,
    nodes_cnt: c_int,
    cpus_cnt: c_int,
    cpu2node: *mut c_int,
    node_info: c_int,
    show_src: bool,
    show_all: bool,
    use_stdio: bool,
    stats_only: bool,
    symbol_full: bool,
    stitch_lbr: bool,
    shared_clines_stats: c2c_stats,
    shared_clines: c_int,
    display: c_int,
    coalesce: *const c_char,
    cl_sort: *mut c_char,
    cl_resort: *mut c_char,
    cl_output: *mut c_char,
}

