macro_rules! cstr { ($s:literal) => { concat!($s, "\0").as_ptr() as *const c_char } }
macro_rules! MIN { ($a:expr, $b:expr) => { if $a < $b { $a } else { $b } } }
macro_rules! HEADER_LOW { ($h:literal) => { c2c_header { line: [c2c_header_line { text: ptr::null(), span: 0 }, c2c_header_line { text: cstr!($h), span: 0 }] } } }
macro_rules! HEADER_BOTH { ($h0:literal, $h1:literal) => { c2c_header { line: [c2c_header_line { text: cstr!($h0), span: 0 }, c2c_header_line { text: cstr!($h1), span: 0 }] } } }
macro_rules! HEADER_SPAN { ($h0:literal, $h1:literal, $s:expr) => { c2c_header { line: [c2c_header_line { text: cstr!($h0), span: $s }, c2c_header_line { text: cstr!($h1), span: 0 }] } } }
macro_rules! HEADER_SPAN_LOW { ($h:literal) => { c2c_header { line: [c2c_header_line { text: ptr::null(), span: 0 }, c2c_header_line { text: cstr!($h), span: 0 }] } } }

unsafe fn container_c2c_he_from_he(he: *mut hist_entry) -> *mut c2c_hist_entry { he as *mut c2c_hist_entry }
unsafe fn container_c2c_fmt_from_fmt(fmt: *mut perf_hpp_fmt) -> *mut c2c_fmt { fmt as *mut c2c_fmt }
