unsafe extern "C" fn c2c_he_zalloc(size: size_t) -> *mut c_void {
    let c2c_he = zalloc(size + size_of::<c2c_hist_entry>()) as *mut c2c_hist_entry;
    if c2c_he.is_null() { return ptr::null_mut(); }
    (*c2c_he).cpuset = bitmap_zalloc(c2c.cpus_cnt);
    if (*c2c_he).cpuset.is_null() { goto_out_free(c2c_he); return ptr::null_mut(); }
    (*c2c_he).nodeset = bitmap_zalloc(c2c.nodes_cnt);
    if (*c2c_he).nodeset.is_null() { goto_out_free(c2c_he); return ptr::null_mut(); }
    (*c2c_he).node_stats = calloc(c2c.nodes_cnt as size_t, size_of::<c2c_stats>()) as *mut c2c_stats;
    if (*c2c_he).node_stats.is_null() { goto_out_free(c2c_he); return ptr::null_mut(); }
    init_stats(&mut (*c2c_he).cstats.lcl_hitm); init_stats(&mut (*c2c_he).cstats.rmt_hitm); init_stats(&mut (*c2c_he).cstats.lcl_peer); init_stats(&mut (*c2c_he).cstats.rmt_peer); init_stats(&mut (*c2c_he).cstats.load);
    &mut (*c2c_he).he as *mut _ as *mut c_void
}
unsafe fn goto_out_free(c2c_he: *mut c2c_hist_entry) { zfree(&mut (*c2c_he).nodeset as *mut _ as *mut *mut c_void); zfree(&mut (*c2c_he).cpuset as *mut _ as *mut *mut c_void); free(c2c_he as *mut c_void); }
unsafe extern "C" fn c2c_he_free(he: *mut c_void) { let c2c_he = container_c2c_he_from_he(he as *mut hist_entry); if !(*c2c_he).hists.is_null() { hists__delete_all_entries(&mut (*(*c2c_he).hists).hists); perf_hpp__reset_output_field(&mut (*(*c2c_he).hists).list); zfree(&mut (*c2c_he).hists as *mut _ as *mut *mut c_void); } zfree(&mut (*c2c_he).cpuset as *mut _ as *mut *mut c_void); zfree(&mut (*c2c_he).nodeset as *mut _ as *mut *mut c_void); zfree(&mut (*c2c_he).nodestr as *mut _ as *mut *mut c_void); zfree(&mut (*c2c_he).node_stats as *mut _ as *mut *mut c_void); free(c2c_he as *mut c_void); }
static mut c2c_entry_ops: hist_entry_ops = hist_entry_ops { new: c2c_he_zalloc, free: c2c_he_free };

unsafe extern "C" fn c2c_hists__init(hists: *mut c2c_hists, sort: *const c_char, nr_header_lines: c_int, env: *mut perf_env) -> c_int { __hists__init(&mut (*hists).hists, &mut (*hists).list); perf_hpp_list__init(&mut (*hists).list); (*hists).list.nr_header_lines = nr_header_lines; let ret = hpp_list__parse(&mut (*hists).list, ptr::null(), sort, env); if ret != 0 { perf_hpp__reset_output_field(&mut (*hists).list); } ret }
unsafe fn he__get_c2c_hists(he: *mut hist_entry, sort: *const c_char, nr_header_lines: c_int, env: *mut perf_env) -> *mut c2c_hists { let c2c_he = container_c2c_he_from_he(he); if !(*c2c_he).hists.is_null() { return (*c2c_he).hists; } let h = zalloc(size_of::<c2c_hists>()) as *mut c2c_hists; (*c2c_he).hists = h; if h.is_null() { return ptr::null_mut(); } if c2c_hists__init(h, sort, nr_header_lines, env) != 0 { (*c2c_he).hists = ptr::null_mut(); free(h as *mut c_void); return ptr::null_mut(); } h }
unsafe fn c2c_he__set_evsel(c2c_he: *mut c2c_hist_entry, evsel: *mut evsel) { (*c2c_he).evsel = evsel; }
unsafe fn c2c_he__set_cpu(c2c_he: *mut c2c_hist_entry, sample: *mut perf_sample) { if WARN_ONCE((*sample).cpu == u32::MAX, cstr!("WARNING: no sample cpu value")) { return; } if (*sample).cpu >= c2c.cpus_cnt as u32 { return; } __set_bit((*sample).cpu as c_int, (*c2c_he).cpuset); }
unsafe fn c2c_he__set_node(c2c_he: *mut c2c_hist_entry, sample: *mut perf_sample) { if (*sample).phys_addr == 0 { (*c2c_he).paddr_zero = true; return; } let node = mem2node__node(&mut c2c.mem2node, (*sample).phys_addr); if WARN_ONCE(node < 0, cstr!("WARNING: failed to find node\n")) { return; } if node >= c2c.nodes_cnt { return; } __set_bit(node, (*c2c_he).nodeset); if (*c2c_he).paddr != (*sample).phys_addr { (*c2c_he).paddr_cnt += 1; (*c2c_he).paddr = (*sample).phys_addr; } }
unsafe fn compute_stats(c2c_he: *mut c2c_hist_entry, stats_: *mut c2c_stats, weight: u64) { let cstats = &mut (*c2c_he).cstats; if (*stats_).rmt_hitm != 0 { update_stats(&mut cstats.rmt_hitm, weight); } else if (*stats_).lcl_hitm != 0 { update_stats(&mut cstats.lcl_hitm, weight); } else if (*stats_).rmt_peer != 0 { update_stats(&mut cstats.rmt_peer, weight); } else if (*stats_).lcl_peer != 0 { update_stats(&mut cstats.lcl_peer, weight); } else if (*stats_).load != 0 { update_stats(&mut cstats.load, weight); } }
unsafe fn perf_c2c__has_annotation(list: *mut perf_hpp_list) -> bool { if use_browser != 1 { return false; } list.is_null() || (*list).sym != 0 }
unsafe fn perf_c2c__evsel_hists_inc_stats(evsel: *mut evsel, he: *mut hist_entry, sample: *mut perf_sample) { let evsel_hists = evsel__hists(evsel); hists__inc_nr_samples(evsel_hists, (*he).filtered); (*evsel_hists).stats.total_period += (*sample).period; if (*he).filtered == 0 { (*evsel_hists).stats.total_non_filtered_period += (*sample).period; } }

unsafe extern "C" fn process_sample_event(_tool: *const perf_tool, event: *mut perf_event, sample: *mut perf_sample, machine: *mut machine) -> c_int { let evsel = (*sample).evsel; let mut c2c_hists = &mut c2c.hists as *mut c2c_hists; let mut stats_: c2c_stats = core::mem::zeroed(); let mut al: addr_location = core::mem::zeroed(); let mut mi: *mut mem_info = ptr::null_mut(); let mut ret: c_int; addr_location__init(&mut al); if machine__resolve(machine, &mut al, sample) < 0 { pr_debug(cstr!("problem processing %s (%u) event at offset %#lx, skipping it.\n"), perf_event__name((*event).header.type_), (*event).header.type_, (*sample).file_offset); ret = -1; goto_out_process(mi, &mut al); return ret; } if c2c.stitch_lbr { thread__set_lbr_stitch_enable(al.thread, true); } let cursor = get_tls_callchain_cursor(); ret = sample__resolve_callchain(sample, cursor, ptr::null_mut(), &mut al, sysctl_perf_event_max_stack); if ret != 0 { goto_out_process(mi, &mut al); return ret; } mi = sample__resolve_mem(sample, &mut al); if mi.is_null() { ret = -ENOMEM; goto_out_process(mi, &mut al); return ret; } c2c_decode_stats(&mut stats_, mi); let mut he = hists__add_entry_ops(&mut (*c2c_hists).hists, &mut c2c_entry_ops, &mut al, ptr::null_mut(), ptr::null_mut(), mi, ptr::null_mut(), sample, true); if he.is_null() { ret = -ENOMEM; goto_out_process(mi, &mut al); return ret; } let mut c2c_he = container_c2c_he_from_he(he); c2c_add_stats(&mut (*c2c_he).stats, &mut stats_); c2c_add_stats(&mut (*c2c_hists).stats, &mut stats_); c2c_he__set_cpu(c2c_he, sample); c2c_he__set_node(c2c_he, sample); c2c_he__set_evsel(c2c_he, evsel); hists__inc_nr_samples(&mut (*c2c_hists).hists, (*he).filtered); if perf_c2c__has_annotation(ptr::null_mut()) { perf_c2c__evsel_hists_inc_stats(evsel, he, sample); addr_map_symbol__inc_samples(mem_info__iaddr(mi), sample); } ret = hist_entry__append_callchain(he, sample); if ret == 0 { let mut cpu = if (*sample).cpu == u32::MAX { 0 } else { (*sample).cpu as c_int }; if cpu < 0 || cpu >= c2c.cpus_cnt { cpu = 0; } let node = *c2c.cpu2node.add(cpu as usize); c2c_hists = he__get_c2c_hists(he, c2c.cl_sort, 2, (*machine).env); if c2c_hists.is_null() { ret = -ENOMEM; goto_out_process(mi, &mut al); return ret; } he = hists__add_entry_ops(&mut (*c2c_hists).hists, &mut c2c_entry_ops, &mut al, ptr::null_mut(), ptr::null_mut(), mi, ptr::null_mut(), sample, true); if he.is_null() { ret = -ENOMEM; goto_out_process(mi, &mut al); return ret; } c2c_he = container_c2c_he_from_he(he); c2c_add_stats(&mut (*c2c_he).stats, &mut stats_); c2c_add_stats(&mut (*c2c_hists).stats, &mut stats_); if node >= 0 && node < c2c.nodes_cnt { c2c_add_stats((*c2c_he).node_stats.add(node as usize), &mut stats_); } compute_stats(c2c_he, &mut stats_, (*sample).weight); c2c_he__set_cpu(c2c_he, sample); c2c_he__set_node(c2c_he, sample); c2c_he__set_evsel(c2c_he, evsel); hists__inc_nr_samples(&mut (*c2c_hists).hists, (*he).filtered); ret = hist_entry__append_callchain(he, sample); } goto_out_process(mi, &mut al); ret }
unsafe fn goto_out_process(mi: *mut mem_info, al: *mut addr_location) { mem_info__put(mi); addr_location__exit(al); }

unsafe fn symbol_width(hists_: *mut hists, se: *mut sort_entry) -> c_int { let mut width = hists__col_len(hists_, (*se).se_width_idx); if !c2c.symbol_full { width = MIN!(width, SYMBOL_WIDTH); } width }
unsafe extern "C" fn c2c_width(fmt: *mut perf_hpp_fmt, _hpp: *mut perf_hpp, hists_: *mut hists) -> c_int { let c2c_fmt = container_c2c_fmt_from_fmt(fmt); let dim = (*c2c_fmt).dim; if dim == &mut dim_symbol || dim == &mut dim_srcline { return symbol_width(hists_, (*dim).se); } if !(*dim).se.is_null() { hists__col_len(hists_, (*(*dim).se).se_width_idx) } else { (*dim).width } }
unsafe extern "C" fn c2c_header(fmt: *mut perf_hpp_fmt, hpp: *mut perf_hpp, hists_: *mut hists, line: c_int, span: *mut c_int) -> c_int { let hpp_list = (*hists_).hpp_list; let c2c_fmt = container_c2c_fmt_from_fmt(fmt); let dim = (*c2c_fmt).dim; let width = c2c_width(fmt, hpp, hists_); let mut text: *const c_char = ptr::null(); if !(*dim).se.is_null() { text = (*dim).header.line[line as usize].text; if text.is_null() && line == (*hpp_list).nr_header_lines - 1 { text = (*(*dim).se).se_header; } } else { text = (*dim).header.line[line as usize].text; if *span != 0 { *span -= 1; return 0; } else { *span = (*dim).header.line[line as usize].span; } } if text.is_null() { text = cstr!(""); } scnprintf((*hpp).buf, (*hpp).size, cstr!("%*s"), width, text) }
unsafe fn hex_str(buf: *mut c_char, v: u64) -> *mut c_char { scnprintf(buf, 20, cstr!("0x%lx"), v); buf }
unsafe extern "C" fn dcacheline_cmp(_fmt: *mut perf_hpp_fmt, left: *mut hist_entry, right: *mut hist_entry) -> int64_t { sort__dcacheline_cmp(left, right) }
